// napi-rs style bundled loader: direct adjacent requires with a platform
// cascade. The real generated loader sniffs `process`/`fs` to pick one
// file; napi-vm guests are deny-by-default with no `process` global, so
// this loader probes each candidate and keeps the first one that
// initializes. Undeclared files fail with "not allowlisted" and foreign
// binaries fail their preflight; both are caught below.
//
// Only files the host authorized (declared host-platform artifacts with
// matching SHA-256 digests) can initialize here.
const candidates = [
  './node-rdev.win32-x64-msvc.node',
  './node-rdev.win32-arm64-msvc.node',
  './node-rdev.linux-x64-gnu.node',
  './node-rdev.linux-x64-musl.node',
  './node-rdev.linux-arm64-gnu.node',
  './node-rdev.linux-arm64-musl.node',
  './node-rdev.darwin-x64.node',
  './node-rdev.darwin-arm64.node',
];

let nativeBinding = null;
let loadError = null;
for (const file of candidates) {
  try {
    nativeBinding = require(file);
    break;
  } catch (error) {
    loadError = error;
  }
}

if (!nativeBinding) {
  if (loadError) throw loadError;
  throw new Error('Failed to load native binding');
}

module.exports = nativeBinding;
